import React from 'react';
import { Link } from 'react-router-dom';
import './menu-principal.css';
// Importando bibliotecas e funcionalidades
import { useState } from "react";
import { FaHome, FaMedal, FaUser, FaEllipsisH, FaVolumeUp, FaVolumeMute, FaStar, FaHeart } from "react-icons/fa";

const menuPrincipal = () => {
  
  const Sidebar = () => {
    const [isSoundOn, setSoundOn] = useState(true);
    const [quirons, setQuirons] = useState(350); // Pontuação inicial
    const [vidas, setVidas] = useState(4); // Número inicial de vidas

    // Alterna o estado do som
    const toggleSound = () => {
      setSoundOn(!isSoundOn);
      console.log(isSoundOn ? "Som desativado" : "Som ativado");
    };

    // Atualiza o número de quirons e vidas (exemplo de função)
    const updateStats = (newQuirons, newVidas) => {
      setQuirons(newQuirons);
      setVidas(newVidas);
    };

    // Navegação lateral
    return (
      <div className="sidebar">
        <h1 className="logo">FISIOGAME</h1>
        <ul className="menu">
          <li className="menu-item active">
            <FaHome /> Início
          </li>
          <li className="menu-item">
            <FaMedal /> Ranking
          </li>
          <li className="menu-item">
            <FaUser /> Perfil
          </li>
          <li className="menu-item">
            <FaEllipsisH /> Mais
          </li>
        </ul>
      </div>
    );
  };

  const MainContent = () => {
    const handleButtonClick = (subject) => {
      alert(`Você selecionou: ${subject}`);
    };

    return (
      <div className="main-content">
        <div className="header">
          <h2>Selecione um assunto para continuar</h2>
        </div>
        <div className="subjects">
          <button className="subject-btn cyan" onClick={() => handleButtonClick("Membrana Celular")}>
            🦠 Membrana Celular
          </button>
          <button className="subject-btn orange" onClick={() => handleButtonClick("Fisiologia Muscular")}>
            💪 Fisiologia Muscular
          </button>
          <button className="subject-btn green" onClick={() => handleButtonClick("Sistema Nervoso")}>
            🧠 Sistema Nervoso
          </button>
          <button className="subject-btn red" onClick={() => handleButtonClick("Sistema Circulatório")}>
            🩸 Sistema Circulatório
          </button>
          <button className="subject-btn blue" onClick={() => handleButtonClick("Sistema Urinário")}>
            🩺 Sistema Urinário
          </button>
          <button className="subject-btn teal" onClick={() => handleButtonClick("Sistema Respiratório")}>
            🌬️ Sistema Respiratório
          </button>
          <button className="next-btn">▶</button>
        </div>
      </div>
    );
  };

  const RightBar = ({ isSoundOn, toggleSound, quirons, vidas }) => {
    return (
      <div className="right-bar">
        <button className="sound-btn" onClick={toggleSound}>
          {isSoundOn ? (
            <>
              <FaVolumeUp /> Desativar Som
            </>
          ) : (
            <>
              <FaVolumeMute /> Ativar Som
            </>
          )}
        </button>
        <div className="stats">
          <p>
            <FaStar /> {quirons} Quirons
          </p>
          <p>
            <FaHeart /> {vidas} Vidas
          </p>
        </div>
      </div>
    );
  };

  const App = () => {
    const [isSoundOn, setSoundOn] = useState(true);
    const [quirons, setQuirons] = useState(350);
    const [vidas, setVidas] = useState(4);

    const toggleSound = () => setSoundOn(!isSoundOn);

    return (
      <div className="app">
        <Sidebar />
        <MainContent />
        <RightBar isSoundOn={isSoundOn} toggleSound={toggleSound} quirons={quirons} vidas={vidas} />
      </div>
    );
  };

}
export default menuPrincipal;
